// clang-format on

inline bool IsSafeCell(int gx, int gy) {
    if (gx < 0 || gy < 0 || gx >= kMenuMaskW || gy >= kMenuMaskH)
        return false;
    int idx = gy * kMenuMaskW + gx;
    return (kMenuMaskBits[idx >> 5] >> (idx & 31)) & 1u;
}

// nx, ny normalized [0,1] over the menu background texture (== normalized
// screen position, since the art is stretched to exactly fill the screen).
inline bool IsSafe(float nx, float ny) {
    const int gx = static_cast<int>(nx * static_cast<float>(kMenuMaskW));
    const int gy = static_cast<int>(ny * static_cast<float>(kMenuMaskH));
    return IsSafeCell(gx, gy);
}

